const appearanceDefaults={sidebarWidth:232,artBackground:false,heroVisible:true,theme:'forest',accent:'#d9f299',radius:12,density:'comfortable',font:'Manrope',scale:100,artwork:true,motion:true,contrast:100};
const palettes={forest:['#151716','#111312','#1d201e','#eeeee7','#858b83','#ffffff12','#d9f299','#1b2313'],paper:['#eeeee5','#e5e7dc','#dfe3d7','#242d24','#63705c','#20302020','#a9c86c','#18240c'],midnight:['#101522','#0b101b','#1a2234','#e5eafa','#939fb8','#ffffff18','#b5c7ff','#15203d'],sepia:['#e8dfce','#ded3bd','#d5c8ae','#332c22','#776952','#332c2224','#b68b47','#201a10'],black:['#000000','#050505','#111111','#f2f2f2','#a0a0a0','#ffffff28','#d9f299','#15200c']};
Object.assign(palettes,{ocean:['#101e22','#0b171b','#182b30','#e4f1ee','#8ea9a9','#ffffff18','#96ddd1','#102421'],rose:['#21181d','#191216','#30222b','#f1e6eb','#b09aa7','#ffffff18','#edb5ca','#301321'],sand:['#27231b','#1d1a14','#352f23','#eee9db','#ada38d','#ffffff18','#dcc78e','#28200d']});
function sanitizeAppearance(x){const d={...appearanceDefaults};if(!x||typeof x!=='object')return d;if(Object.hasOwn(palettes,x.theme))d.theme=x.theme;if(/^#[0-9a-f]{6}$/i.test(x.accent))d.accent=x.accent;for(const [k,min,max]of [['radius',0,28],['scale',85,120],['contrast',80,120]])if(Number.isFinite(+x[k]))d[k]=Math.min(max,Math.max(min,+x[k]));if(['comfortable','compact'].includes(x.density))d.density=x.density;if(['Manrope','Segoe UI','Georgia'].includes(x.font))d.font=x.font;for(const k of ['artwork','motion'])if(typeof x[k]==='boolean')d[k]=x[k];for(const k of ['artBackground','heroVisible'])if(typeof x[k]==='boolean')d[k]=x[k];if(Number.isFinite(+x.sidebarWidth))d.sidebarWidth=Math.max(200,Math.min(290,+x.sidebarWidth));return d}
let appearance;try{appearance=sanitizeAppearance(JSON.parse(localStorage.getItem('soulroom.appearance')))}catch{appearance={...appearanceDefaults}}
let enabledSources;try{enabledSources=JSON.parse(localStorage.getItem('soulroom.sources'));if(!Array.isArray(enabledSources))throw Error();enabledSources=enabledSources.filter(x=>['yandex','soundcloud','spotify'].includes(x));if(!enabledSources.length)throw Error()}catch{enabledSources=['yandex','soundcloud','spotify']}
function applyAppearance(){document.body.dataset.artBackground=appearance.artBackground;document.body.dataset.heroVisible=appearance.heroVisible;document.documentElement.style.setProperty('--sidebar-width',appearance.sidebarWidth+'px');const p=palettes[appearance.theme];document.body.classList.remove('light');['bg','side','panel','text','muted','line','accent','ink'].forEach((k,i)=>document.documentElement.style.setProperty('--'+k,k==='accent'?appearance.accent:p[i]));document.documentElement.style.setProperty('--radius',appearance.radius+'px');document.documentElement.style.setProperty('--ui-font',`"${appearance.font}"`);document.documentElement.style.setProperty('--ui-scale',appearance.scale/100);document.body.dataset.density=appearance.density;document.body.dataset.artwork=appearance.artwork;document.body.dataset.motion=appearance.motion;document.body.dataset.palette=appearance.theme;document.documentElement.style.setProperty('--image-contrast',appearance.contrast/100);localStorage.setItem('soulroom.appearance',JSON.stringify(appearance))}
applyAppearance();
function appearanceScreen(){return heading('Как тебе нравится.','Твоё оформление сохраняется на этом устройстве.')+`<div class="appearance-preview"><span class="eyebrow">ТВОЙ ОБЛИК</span><h2>Пространство звучит по-твоему.</h2><p>Цвет, ритм, детали — всё под тебя.</p><button class="primary" data-room="0">▶ Послушать сессию</button></div><div class="settings-card"><h3>Атмосфера</h3><div class="theme-presets">${[['forest','Лес'],['paper','День'],['midnight','Полночь'],['sepia','Бумага'],['black','Чёрный'],['ocean','Океан'],['rose','Роза'],['sand','Песок']].map(([k,v])=>`<button data-preset="${k}" class="preset ${appearance.theme===k?'selected':''}" style="--swatch:${palettes[k][0]};--swatch-text:${palettes[k][3]}"><span>Aa</span>${v}</button>`).join('')}</div></div><div class="settings-card appearance-controls"><h3>Тонкая настройка</h3><label>Акцент <input type="color" data-appearance="accent" value="${appearance.accent}"></label><label>Скругление <output id="radiusValue">${appearance.radius} px</output><input type="range" data-appearance="radius" aria-label="Скругление" min="0" max="28" value="${appearance.radius}"></label><label>Размер текста <output id="scaleValue">${appearance.scale}%</output><input type="range" data-appearance="scale" aria-label="Размер текста" min="85" max="120" value="${appearance.scale}"></label><label>Контраст обложек <output id="contrastValue">${appearance.contrast}%</output><input type="range" data-appearance="contrast" aria-label="Контраст обложек" min="80" max="120" value="${appearance.contrast}"></label><label>Плотность <select data-appearance="density" aria-label="Плотность">${[['comfortable','Свободно'],['compact','Компактно']].map(([k,v])=>`<option value="${k}" ${appearance.density===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Шрифт <select data-appearance="font" aria-label="Шрифт">${['Manrope','Segoe UI','Georgia'].map(k=>`<option ${appearance.font===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Показывать обложки <input type="checkbox" data-appearance="artwork" ${appearance.artwork?'checked':''}></label><label>Ширина меню <output id="sidebarWidthValue">${appearance.sidebarWidth} px</output><input type="range" data-appearance="sidebarWidth" aria-label="Ширина меню" min="200" max="290" value="${appearance.sidebarWidth}"></label><label>Фон из обложки трека <input type="checkbox" data-appearance="artBackground" ${appearance.artBackground?'checked':''}></label><label>Показывать главный баннер <input type="checkbox" data-appearance="heroVisible" ${appearance.heroVisible?'checked':''}></label><label>Плавные переходы <input type="checkbox" data-appearance="motion" ${appearance.motion?'checked':''}></label></div><div class="settings-card"><h3>Сохранить свой облик</h3><p>Перенеси оформление на другое устройство или поделись своим набором настроек.</p><div class="settings-actions"><button class="primary" id="exportAppearance">Экспортировать</button><button class="secondary" id="importAppearance">Импортировать</button><button class="secondary" id="resetAppearance">Сбросить облик</button></div><input id="appearanceFile" type="file" accept="application/json,.json" hidden></div>`}
const serviceNames={yandex:'Яндекс.Музыка',soundcloud:'SoundCloud',spotify:'Spotify'};
let serviceState={},statusGeneration=0;
function connectionsScreen(){return heading('Три сервиса. Одна комната.','Подключи свои источники и выбери, где искать музыку.')+`<div class="service-summary">${Object.entries(serviceNames).map(([k,v])=>`<div><span class="service-letter ${k}">${v[0]}</span><strong>${v}</strong><span id="state-${k}" class="service-state">${backend?'Проверяем…':'Нужен локальный сервер'}</span></div>`).join('')}</div>${!backend?'<div class="settings-card"><h3>Подключения работают в приложении</h3><p>Открой локальную версию через start.cmd. Токены сохраняются только на этом компьютере. Веб-версия поддерживает свою музыку и оформление.</p></div>':''}<div class="settings-card"><h3>Источники общего поиска</h3><p>Результаты из выбранных каталогов собираются вместе. Недоступный сервис не мешает остальным.</p><div class="source-toggles">${Object.entries(serviceNames).map(([k,v])=>`<label><input type="checkbox" data-source-enabled="${k}" ${enabledSources.includes(k)?'checked':''}>${v}</label>`).join('')}</div></div><div class="settings-card"><div class="service-heading"><h3>Яндекс.Музыка</h3><span>Каталог · воспроизведение</span></div><p>Вставь личный OAuth-токен. Возможности прослушивания зависят от аккаунта и подписки сервиса.</p><form id="yandexForm"><label for="ymToken">OAuth-токен</label><input id="ymToken" type="password" autocomplete="off" placeholder="OAuth-токен" ${!backend?'disabled':''}><button class="primary" ${!backend?'disabled':''}>Подключить Яндекс</button></form><p id="detail-yandex" class="service-detail"></p></div><div class="settings-card"><div class="service-heading"><h3>SoundCloud</h3><span>Каталог · воспроизведение</span></div><p>Публичный каталог подключается автоматически. При необходимости укажи свой Client ID. Недоступные треки Go+ не воспроизводятся.</p><form id="soundcloudForm"><label for="scId">Client ID — необязательно</label><input id="scId" autocomplete="off" placeholder="Client ID SoundCloud" ${!backend?'disabled':''}><button class="primary" ${!backend?'disabled':''}>Подключить SoundCloud</button></form><p id="detail-soundcloud" class="service-detail"></p></div><div class="settings-card"><div class="service-heading"><h3>Spotify</h3><span>Каталог · поиск версии</span></div><p>Подключи каталог через Client ID и Client Secret. Для прослушивания полного трека найди его версию в Яндексе или SoundCloud.</p><form id="spotifyForm"><label for="spId">Client ID</label><input id="spId" autocomplete="off" placeholder="Client ID" ${!backend?'disabled':''}><label for="spSecret">Client Secret</label><input id="spSecret" type="password" autocomplete="off" placeholder="Client Secret" ${!backend?'disabled':''}><button class="primary" ${!backend?'disabled':''}>Подключить Spotify</button></form><p id="detail-spotify" class="service-detail"></p></div><div class="settings-actions"><button class="primary" id="refreshConnections" ${!backend?'disabled':''}>Проверить подключения</button><button class="secondary" data-page="search">Найти музыку ↗</button></div><p>Файлы с устройства доступны дополнительно — они остаются частью общей коллекции.</p>`}
async function refreshConnections(){if(!backend)return;const version=++statusGeneration;try{const d=await api('status');if(version!==statusGeneration)return;serviceState=d.sources||{};for(const k of Object.keys(serviceNames)){const s=serviceState[k]||{},node=$('#state-'+k),detail=$('#detail-'+k);if(node){node.textContent=s.connected?'Подключён':'Не подключён';node.classList.toggle('is-on',!!s.connected)}if(detail)detail.textContent=s.connected?(typeof s.user==='string'?s.user: s.user?.displayName||s.user?.name||'Соединение с сервисом установлено.'):(typeof s.error==='string'?'Источник недоступен: '+s.error:'Добавь данные подключения и проверь снова.')}}catch(e){if(page==='connections')for(const k of Object.keys(serviceNames)){const node=$('#state-'+k);if(node)node.textContent='Не удалось проверить'}toast(e.message)}}
const originalRender=render;render=function(){originalRender();if(page==='appearance'){$('#crumb').textContent='ОФОРМЛЕНИЕ';$('#view').innerHTML=appearanceScreen()}if(page==='connections'){$('#view').innerHTML=connectionsScreen();refreshConnections()}};
const appearanceNav=document.createElement('button');appearanceNav.dataset.page='appearance';appearanceNav.setAttribute('aria-label','Оформление');appearanceNav.innerHTML='◐ <span>Оформление</span>';document.querySelector('.sidebar nav').append(appearanceNav);
theme=function(){const next=appearance.theme==='paper'?'forest':'paper';appearance.theme=next;appearance.accent=palettes[next][6];applyAppearance();if(page==='appearance')render()};
document.addEventListener('input',e=>{const k=e.target.dataset.appearance;if(!k)return;appearance=sanitizeAppearance({...appearance,[k]:e.target.type==='checkbox'?e.target.checked:e.target.value});applyAppearance();const out=$('#'+k+'Value');if(out)out.textContent=appearance[k]+(['radius','sidebarWidth'].includes(k)?' px':'%')});
document.addEventListener('change',e=>{const source=e.target.dataset.sourceEnabled;if(!source)return;const next=[...document.querySelectorAll('[data-source-enabled]:checked')].map(x=>x.dataset.sourceEnabled);if(!next.length){e.target.checked=true;toast('Оставь хотя бы один источник поиска.');return}enabledSources=next;localStorage.setItem('soulroom.sources',JSON.stringify(next))});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.preset){appearance.theme=b.dataset.preset;appearance.accent=palettes[appearance.theme][6];applyAppearance();render()}if(b.id==='refreshConnections')refreshConnections();if(b.id==='resetAppearance'){appearance={...appearanceDefaults};applyAppearance();render();toast('Начальное оформление восстановлено.')}if(b.id==='exportAppearance'){const url=URL.createObjectURL(new Blob([JSON.stringify({format:'soulroom-appearance',version:1,appearance},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='soulroom-appearance.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}if(b.id==='importAppearance')$('#appearanceFile').click()});
document.addEventListener('change',async e=>{if(e.target.id!=='appearanceFile')return;const f=e.target.files[0];if(!f)return;try{if(f.size>30000)throw Error();const parsed=JSON.parse(await f.text());if(parsed.format!=='soulroom-appearance'||!parsed.appearance||!Object.hasOwn(palettes,parsed.appearance.theme))throw Error();appearance=sanitizeAppearance(parsed.appearance);applyAppearance();render();toast('Оформление применено.')}catch{toast('Не удалось прочитать оформление. Выбери JSON-файл soulroom.')}});
document.addEventListener('submit',async e=>{if(e.target.id!=='soundcloudForm')return;e.preventDefault();if(!backend)return;const clientId=$('#scId').value.trim();if(clientId&&!/^[a-z0-9]{32}$/i.test(clientId))return toast('Client ID SoundCloud должен содержать 32 буквы или цифры.');const button=e.target.querySelector('button');button.disabled=true;try{await api('settings',{method:'PUT',body:JSON.stringify({soundcloud:{clientId}})});e.target.reset();toast('SoundCloud настроен.');await refreshConnections()}catch(err){toast(err.message)}finally{button.disabled=false}});
$('#theme').onclick=()=>theme();

// SoundCloud network controls use the same isolated transport as audio/HLS.
const oldConnectionsScreen=connectionsScreen;connectionsScreen=function(){return oldConnectionsScreen()+`<div class="settings-card"><h3>SoundCloud в недоступной сети</h3><p>Автоматически: прямое соединение, затем резервный сервер. После успешного переключения следующие запросы сразу используют рабочий маршрут. Резервный сервер получает только публичные запросы SoundCloud, без OAuth-токенов и cookie.</p><form id="scNetworkForm"><label for="scTransport">Способ подключения</label><select id="scTransport"><option value="auto">Автоматически</option><option value="direct">Прямое подключение / свой прокси</option><option value="relay">Резервные серверы</option></select><label for="scProxy">Свой HTTP(S)-прокси — необязательно</label><input id="scProxy" placeholder="http://127.0.0.1:8080" autocomplete="off"><label class="inline-check"><input id="scSystemProxy" type="checkbox">Использовать системный прокси Windows</label><p>Системные настройки Windows не меняются. Прокси применяется только к SoundCloud.</p><div class="settings-actions"><button class="primary" ${!backend?'disabled':''}>Сохранить маршрут</button><button type="button" class="secondary" id="testScNetwork" ${!backend?'disabled':''}>Проверить соединение</button></div></form><p id="scNetworkStatus" role="status">${backend?'Загружаем состояние…':'Доступно в локальном приложении.'}</p><p>Доступность API и доступность аудио — разные проверки. Ограничения конкретного трека и подписки не устраняются сменой маршрута.</p></div>`};
async function loadScNetwork(){if(!backend||page!=='connections')return;try{const n=await api('network');if(page!=='connections')return;$('#scTransport').value=n.transportMode||'auto';$('#scSystemProxy').checked=!!n.useSystemProxy;$('#scNetworkStatus').textContent=`Маршрут: ${n.relays?.working?'резервный сервер':n.active?'прокси':'прямое соединение'}. Резервных серверов: ${n.relays?.relays?.length||0}.`+(n.error?' '+n.error:'')}catch(e){if($('#scNetworkStatus'))$('#scNetworkStatus').textContent=e.message}}
const renderWithAppearance=render;render=function(){renderWithAppearance();if(page==='connections')loadScNetwork()};
document.addEventListener('submit',async e=>{if(e.target.id!=='scNetworkForm')return;e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{await api('network',{method:'PUT',body:JSON.stringify({proxy:$('#scProxy').value.trim(),useSystemProxy:$('#scSystemProxy').checked,autoProxy:false})});await api('settings',{method:'PUT',body:JSON.stringify({soundcloud:{transportMode:$('#scTransport').value}})});$('#scProxy').value='';await loadScNetwork();toast('Маршрут SoundCloud сохранён.')}catch(err){toast(err.message)}finally{btn.disabled=false}});
document.addEventListener('click',async e=>{if(e.target.closest('button')?.id!=='testScNetwork')return;const node=$('#scNetworkStatus');node.textContent='Проверяем прямой маршрут и настроенный прокси…';try{const n=await api('network/test',{method:'POST',body:'{}'});if(page!=='connections')return;node.textContent=`Напрямую: ${n.direct?.reachable?'API отвечает ('+n.direct.ms+' мс)':'нет соединения'}. Прокси: ${!n.viaProxy?'не настроен':n.viaProxy.reachable?'API отвечает ('+n.viaProxy.ms+' мс)':'нет соединения'}. Аудиопоток проверяется при воспроизведении.`}catch(err){if(page==='connections')node.textContent=err.message}});
